function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};if($e -is [ArgumentOutOfRangeException]){$r.actualValue=$e.ActualValue};return $r}

