 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$reads);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$throwAt);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$noThrow);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'maximum getter failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($noThrow)
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$reads);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Beq,$firstLabel);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$second);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($firstLabel);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$maximum);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($getter,$base.GetProperty('MaxCharCount').GetMethod)
 $factory=$builder.DefineMethod('CreateFallbackBuffer',$attributes,$buffer,[type[]]@());$il=$factory.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$text);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$replacement.GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$base.GetMethod('CreateFallbackBuffer'));$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($factory,$base.GetMethod('CreateFallbackBuffer'));return $builder.CreateType()
