$encoderType=CustomType 'Encoder';$decoderType=CustomType 'Decoder';$profiles=[Collections.Generic.List[object]]::new();$calls=0
foreach($emitBom in @($false,$true)){foreach($setting in @(@(0,2,0),@(1,2147483647,0),@(2,0,0),@(2,-1,0),@(2,-2147483648,0),@(2,2147483647,0),@(2147483647,1,0),@(2,3,0),@(2,3,1),@(2,3,2),@(1,3,2),@(0,-1,1))){$maximum=[int]$setting[0];$encoder=[Activator]::CreateInstance($encoderType);$decoder=[Activator]::CreateInstance($decoderType);foreach($pair in @(@($encoderType,$encoder),@($decoderType,$decoder))){$pair[0].GetField('Replacement').SetValue($pair[1],'?');$pair[0].GetField('Maximum').SetValue($pair[1],[int]$maximum);$pair[0].GetField('Second').SetValue($pair[1],[int]$setting[1]);$pair[0].GetField('ThrowAt').SetValue($pair[1],[int]$setting[2])};$owner=[Text.Encoding]([Text.UTF8Encoding]::new($emitBom,$false)).Clone();$owner.EncoderFallback=$encoder;$owner.DecoderFallback=$decoder;$m=[Math]::Max(1,$maximum);$rows=[Collections.Generic.List[object]]::new()
 foreach($method in @('GetMaxByteCount','GetMaxCharCount')){$inputs=@(-2147483648,-1,0,1,2,7,1073741823,2147483647)
  foreach($n in $inputs){$encoder.MaximumCalls=0;$decoder.MaximumCalls=0;$encoder.FactoryCalls=0;$decoder.FactoryCalls=0;try{$value=if($method -eq 'GetMaxByteCount'){$owner.GetMaxByteCount($n)}else{$owner.GetMaxCharCount($n)};$result=[ordered]@{ok=$true;count=$value}}catch{$result=Failure-Of $_};$rows.Add([ordered]@{method=$method;input=$n;result=$result;encoderMaximumCalls=$encoder.MaximumCalls;decoderMaximumCalls=$decoder.MaximumCalls;encoderFactoryCalls=$encoder.FactoryCalls;decoderFactoryCalls=$decoder.FactoryCalls});$calls++}
 };$profiles.Add([ordered]@{emitBom=$emitBom;advertisedFirst=$maximum;advertisedSecond=[int]$setting[1];throwAt=[int]$setting[2];rows=$rows.ToArray()})
}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();nativeCalls=$calls;profiles=$profiles.ToArray();qualification='NATIVE_SELECTED_UTF8_CHANGING_AND_THROWING_MAXIMUM_GETTERS_ONLY; NO_FULL_PARITY_OR_TASK_ACCEPTANCE'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS UTF8 maximum getter sequencing capture: $calls calls"
